const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,pathlib,collections
pat=re.compile(r'\\boxed\s*\{([^{}]*)\}')
def vals(s): return pat.findall(s)
for fn in ['results/run100/val_generations/0.jsonl','results/run100/val_generations/50.jsonl','results/run100/val_generations/100.jsonl']:
 rows=[json.loads(x) for x in open(fn)]
 print('\n###',fn)
 cats=collections.Counter(); examples={}
 for i,r in enumerate(rows):
  bs=vals(r['output']); b=bs[-1] if bs else None
  gt=r['gts'].replace(',','').strip()
  # basic numeric exact after $, text etc
  clean=(b or '').replace(',','').replace('$','').strip()
  ok=clean==gt
  log=bool(r['score'])
  if log and not ok: cat='logged1_fixed0'
  elif not log and ok: cat='logged0_fixed1'
  elif log and ok: cat='both1'
  else: cat='both0'
  cats[cat]+=1
  if cat not in examples: examples[cat]=(i,r['gts'],b,len(r['output']),r['output'][-500:])
 print(cats)
 for c,e in examples.items(): print('\n',c,e[:4],repr(e[4]))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:40000});
text(r.output);

