const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,pathlib,collections,statistics
pat=re.compile(r'\\boxed\s*\{([^{}]*)\}')
for typ in ['rollouts','val_generations']:
 print('\n',typ)
 for fn in sorted(pathlib.Path('results/run100',typ).glob('*.jsonl'), key=lambda p:int(p.stem)):
  rs=[json.loads(x) for x in fn.read_text().splitlines() if x.strip()]
  c=collections.Counter(); lens={}
  for r in rs:
   o=r.get('output',''); bs=pat.findall(o); b=bs[-1] if bs else None
   gt=r.get('gts',''); clean=(b or '').replace(',','').replace('$','').strip(); gt=gt.replace(',','').strip()
   fixed=(clean==gt and b is not None)
   logged=bool(r.get('score',r.get('reward',0)))
   trunc=len(o.split()) # approximate
   c[('logged1' if logged else 'logged0','fixed1' if fixed else 'fixed0','box1' if b else 'box0')]+=1
   lens.setdefault(('logged1' if logged else 'logged0','fixed1' if fixed else 'fixed0'),[]).append(len(o))
  print(fn.name,'n',len(rs),'cats',c)
  for k,v in sorted(lens.items()): print(k,'count',len(v),'charsmean',round(statistics.mean(v),1),'p90',sorted(v)[int(.9*len(v))-1])
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000});
text(r.output);

