from rewards.math_verify_reward import compute_score

def last_boxed(s):
    idx=s.rfind('\\boxed')
    if idx<0:return None
    # support boxed{...} only
    j=s.find('{',idx)
    if j<0:return None
    dep=0
    for k in range(j,len(s)):
      if s[k]=='{':dep+=1
      elif s[k]=='}':
       dep-=1
       if dep==0:return s[j+1:k]
    return None

def num(x):
 if x is None:return None
