"""Strict GSM8K reward aligned with the held-out grader.

The staged task requires a response to end with a closed ``\\boxed{...}`` whose
numeric content equals the ground-truth answer.  Math-Verify is intentionally
not used here: it parses arbitrary expressions anywhere in a response and can
therefore reward an unfinished response that never supplies the required box.
"""

import re
from decimal import Decimal, InvalidOperation

# The grader accepts the number in the response's last boxed expression.  GSM8K
# answers are integers (possibly negative); allow a decimal representation too
# so formatting such as ``28.00`` remains numerically equivalent.
_BOXED_RE = re.compile(r"\\boxed\s*\{([^{}]*)\}")
_NUMBER_RE = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$")


def _numeric(value):
    """Return a finite Decimal for a simple numeric answer, otherwise None."""
    if value is None:
        return None
    text = str(value).strip().replace(",", "").replace("$", "")
    if not _NUMBER_RE.fullmatch(text):
        return None
    try:
        number = Decimal(text)
    except InvalidOperation:
        return None
    return number if number.is_finite() else None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    """Give 1 only when the last closed box contains the numeric gold answer."""
    if solution_str is None:
        return 0.0
    matches = _BOXED_RE.findall(str(solution_str))
    if not matches:
        return 0.0
    predicted = _numeric(matches[-1])
    expected = _numeric(ground_truth)
    return 1.0 if predicted is not None and expected is not None and predicted == expected else 0.0
