import json,re,decimal,pathlib
BOX='\\boxed'
def last_content(s):
 i=s.rfind(BOX)
 while i>=0:
  j=s.find('{',i+len(BOX))
  if j<0: return None
  d=0
  for k in range(j,len(s)):
   if s[k]=='{':d+=1
   elif s[k]=='}':
    d-=1
    if d==0:return s[j+1:k]
  return None

def parse(s):
