import json,re,decimal,pathlib
BOX='\\boxed'
def last_content(s):
 i=s.rfind(BOX)
 while i>=0:
  j=s.find('{',i+len(BOX))
  if j<0: return None
  d=0
  for k in range(j,len(s)):
   if s[k]=='{':d+=1
   elif s[k]=='}':
    d-=1
    if d==0:return s[j+1:k]
  return None

def parse(s):
 if s is None:return None
 s=s.replace('\\,','').replace('\\!','')
 # grouped commas or plain decimal, optional surrounding Latex commands/units
 toks=re.findall(r'[-+]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?|[-+]?\.\d+',s)
 # normalize commas, ensure exactly one numeric literal
 if len(toks)!=1:return None
 try:return decimal.Decimal(toks[0].replace(',',''))
 except:return None
for fn in sorted(pathlib.Path('results/run100/val_generations').glob('*.jsonl'),key=lambda p:int(p.stem)):
 rs=[json.loads(x) for x in fn.read_text().splitlines()]; c=0; no=0
 for r in rs:
  b=last_content(r['output']); v=parse(b); g=parse(r['gts']); c+=v is not None and g is not None and v==g; no+=b is None
 print(fn.name,c/len(rs),c,'no_box',no)
